class Solution {
  public int countArrays(int[] digitSum) {
    final long MOD = 1_000_000_007L;
    int V = 5001;
    int[] ds = new int[V];
    for (int v = 0; v < V; v++) {
      int s = 0;
      for (int t = v; t > 0; t /= 10) s += t % 10;
      ds[v] = s;
    }
    long[] dp = new long[V];
    for (int v = 0; v < V; v++) dp[v] = ds[v] == digitSum[0] ? 1 : 0;
    for (int i = 1; i < digitSum.length; i++) {
      long[] nd = new long[V];
      long prefix = 0;
      for (int v = 0; v < V; v++) {
        prefix = (prefix + dp[v]) % MOD;
        if (ds[v] == digitSum[i]) nd[v] = prefix;
      }
      dp = nd;
    }
    long ans = 0;
    for (long v : dp) ans += v;
    return (int) (ans % MOD);
  }
}
